namespace {void commandSnapshot(AlertWindow* d,const File& file){if(!d)return;FileOutputStream out(file);if(out.openedOk())PNGImageFormat().writeImageToStream(d->createComponentSnapshot(d->getLocalBounds()),out);}
AlertWindow* commandDialog(){return dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());}TextEditor* commandEditor(AlertWindow* d,const char* id){return d?dynamic_cast<TextEditor*>(d->findChildWithID(id)):nullptr;}}
void Studio::runProjectCommandChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    auto saved=project;auto file=currentFile;auto undo=undoStack,redo=redoStack;auto selection=selectedNotes;int track=selectedTrack,note=selectedNote;bool wasDirty=dirty;
    perform(stop);releaseKeys();cancelNoteTool();closeCommandPalette();project=emptyProject();currentFile={};selectedTrack=7;selectedNote=-1;selectedNotes.clear();lane()={{.5,.75,60,.7f,.4f,3,4,2},{3,.5,67,.8f}};publish();undoStack.clear();redoStack.clear();setSize(1440,940);resetLayout();auto original=JSON::toString(projectToJson(project));
    check(!searchCommands(paletteEntries(),"local project commands").empty(),"command search discovers offline project commands");
    String text="rename track 8 to \"Strings\"\nuse sound \"Cedar string\" on track \"Strings\"\nset track 8 volume to 50 percent\ntranspose track 8 in pattern 1 up 2 semitones";
    showProjectCommands(text);auto* d=commandDialog();auto* editor=commandEditor(d,"commands");check(editor&&editor->isMultiLine()&&editor->getText()==text,"project command input is a multiline editable local draft");if(d){commandSnapshot(d,folder.getChildFile("local-project-commands.png"));d->exitModalState(0);}check(JSON::toString(projectToJson(project))==original&&undoStack.empty(),"opening and cancelling command input leaves the project and history untouched");
    previewProjectCommands(text,revision);d=commandDialog();editor=commandEditor(d,"resolved-commands");check(editor&&editor->isReadOnly()&&editor->getText().contains("Track 8")&&editor->getText().contains("Cedar string")&&editor->getText().contains("2 semitones"),"review displays resolved channel, sound and exact note transposition");check(JSON::toString(projectToJson(project))==original&&undoStack.empty(),"command preview compiles without editing or creating Undo");if(d){commandSnapshot(d,folder.getChildFile("review-project-commands.png"));d->exitModalState(0);}
    check(applyProjectCommands(text,revision)&&undoStack.size()==1&&project.tracks[7].name=="Strings"&&project.tracks[7].instrument==Instrument::physical&&project.tracks[7].volume==.5f&&lane()[0].pitch==62,"a command batch commits its sound, fader and notes as one Undo");auto result=JSON::toString(projectToJson(project));perform(undoAction);check(JSON::toString(projectToJson(project))==original,"one command Undo restores the exact source song");perform(redoAction);check(JSON::toString(projectToJson(project))==result,"Redo restores the whole resolved command batch");
    auto oldRevision=revision;changed(false);check(!applyProjectCommands("set tempo to 130",oldRevision)&&project.bpm!=130,"stale command reviews cannot apply after another project edit");auto count=undoStack.size();check(applyProjectCommands("set track 8 volume to 50 percent",revision)&&undoStack.size()==count,"commands which already match add no history entry");auto frozen=JSON::toString(projectToJson(project));check(!applyProjectCommands("set tempo to 130\nset track 8 volume to 500 percent",revision)&&JSON::toString(projectToJson(project))==frozen&&undoStack.size()==count,"late command validation failure is atomic in the native editor");
    recording=true;check(!applyProjectCommands("set tempo to 130",revision),"active recording guards native command commits");recording=false;exporting.store(true);check(!applyProjectCommands("set tempo to 130",revision),"active export guards native command commits");exporting.store(false);
    var args(new DynamicObject()),reply;args.getDynamicObject()->setProperty("expected_revision",(int64)revision);args.getDynamicObject()->setProperty("preview",true);args.getDynamicObject()->setProperty("operations",JSON::parse(R"([{"op":"project_commands","text":"set tempo to 101\nmute track 2"}])"));auto beforeRevision=revision;check(handleControlCommand("edit",args,reply).wasOk()&&(bool)reply["preview"]&&(double)reply["candidateProject"]["bpm"]==101&&reply["resolvedCommands"].getArray()->size()==2,"native MCP dry run returns the compiled candidate and resolved command list");check(revision==beforeRevision&&undoStack.size()==count&&JSON::toString(projectToJson(project))==frozen,"MCP dry run does not publish, back up or change the session");
    args.getDynamicObject()->setProperty("preview","true");check(handleControlCommand("edit",args,reply).failed()&&revision==beforeRevision,"native preview requires a real boolean");
    project.patterns[0].length=16;lane()={{0,.5,60,.8f}};engine->position.store(12);publish();check(applyProjectCommands("set pattern 1 length to 8 beats",revision)&&engine->seekRequested.load()==0,"command pattern shortening restarts PAT from zero");
    auto out=folder.getChildFile("command-editor.pulse");Project read;check(saveProject(project,out).wasOk()&&loadProject(out,read).wasOk()&&read.patterns[0].length==8&&read.tracks[7].instrument==Instrument::physical,"native command results persist as ordinary project data");perform(stop);project=std::move(saved);currentFile=file;undoStack=std::move(undo);redoStack=std::move(redo);selectedTrack=track;selectedNote=note;selectedNotes=selection;dirty=wasDirty;publish();
}
void Studio::runProjectCommandTransportTick(){
    auto put=[&](const char* name,bool ok){transportResults.getDynamicObject()->setProperty(name,ok);};auto close=[&](int result){if(auto* d=commandDialog())d->exitModalState(result);};
    if(transportTicks==5800){perform(stop);cancelNoteTool();project=emptyProject();project.loop=true;project.patterns[0].length=4;currentFile={};selectedTrack=7;selectedNote=-1;selectedNotes.clear();lane()={{0,2,60,.8f}};undoStack.clear();redoStack.clear();publish();transportResults.getDynamicObject()->setProperty("nativeCommandsBefore",JSON::toString(projectToJson(project)));showProjectCommands("set tempo to 96\nuse sound \"Cedar string\" on track 8\nset track 8 volume to 50 percent\ntranspose track 8 in pattern 1 up 2 semitones");put("nativeCommandsInput",commandEditor(commandDialog(),"commands")!=nullptr);close(1);}
    if(transportTicks==5810){auto* e=commandEditor(commandDialog(),"resolved-commands");put("nativeCommandsReview",e&&e->isReadOnly()&&e->getText().contains("Track 8")&&e->getText().contains("2 semitones"));put("nativeCommandsPreviewReadOnly",JSON::toString(projectToJson(project))==transportResults["nativeCommandsBefore"].toString()&&undoStack.empty());commandSnapshot(commandDialog(),transportReport.getSiblingFile("native-commands-review.png"));close(1);}
    if(transportTicks==5820){put("nativeCommandsApply",project.bpm==96&&project.tracks[7].instrument==Instrument::physical&&project.tracks[7].volume==.5f&&lane()[0].pitch==62&&undoStack.size()==1);perform(undoAction);put("nativeCommandsUndo",JSON::toString(projectToJson(project))==transportResults["nativeCommandsBefore"].toString());perform(redoAction);put("nativeCommandsRedo",project.bpm==96&&lane()[0].pitch==62);engine->observedPeak.store(0);perform(play);}
    if(transportTicks==5840){put("nativeCommandsAudio",engine->playing.load()&&engine->observedPeak.load()>.001f);perform(stop);showProjectCommands("rename song to \"Do not apply\"");close(1);}
    if(transportTicks==5860)close(0);
    if(transportTicks==5870){put("nativeCommandsCancel",project.title!="Do not apply"&&undoStack.size()==1);showProjectCommands("set tempo to 112");close(1);}
    if(transportTicks==5880){project.notes="Changed during review";changed(false);close(1);}
    if(transportTicks==5890){put("nativeCommandsStale",project.bpm==96&&status.startsWith("Project changed"));showProjectCommands("set tempo to 999");close(1);}
    if(transportTicks==5900){put("nativeCommandsInvalid",project.bpm==96&&commandEditor(commandDialog(),"commands")&&status.contains("Line 1"));close(0);recording=true;put("nativeCommandsRecording",!applyProjectCommands("set tempo to 112",revision));recording=false;showProjectCommands("set tempo to 112");close(1);}
    if(transportTicks==5910)close(2);
    if(transportTicks==5920){auto* e=commandEditor(commandDialog(),"commands");put("nativeCommandsBack",e&&e->getText()=="set tempo to 112"&&project.bpm==96);close(0);auto out=transportReport.getSiblingFile("native-commands.pulse");Project read;put("nativeCommandsPersistence",saveProject(project,out).wasOk()&&loadProject(out,read).wasOk()&&read.bpm==96&&read.tracks[7].instrument==Instrument::physical&&read.patterns[0].lanes[7][0].pitch==62);perform(stop);}
}
